module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);
    wire [4:0] sum;       // Intermediate sum
    wire adjust;          // Adjustment flag for BCD result

    assign sum = A + B + Cin;
    assign adjust = (sum > 9);
    assign Sum = adjust ? (sum - 10) : sum[3:0];
    assign Cout = adjust ? 1 : sum[4];
endmodule

