module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);
	always @(*) begin
		if (clk_a) 
			dataout = data_in;
		else if (clk_b)
			dataout = data_in + 4'b0001;
		else if (arstn)
			dataout = data_in - 4'b0001;
		else if (brstn)
			dataout = ~data_in;
		else if (data_en)
			dataout = 4'b0000;
		else 
			dataout = 4'b1111;
	end
endmodule

